async function products(){const r=await fetch('/data/products.json');if(!r.ok)throw new Error('seed data unavailable');return (await r.json()).products}function card(p){return `<article class="product-card" data-product-id="${p.id}" data-category="${p.category}"><img src="${p.image}" alt="${p.name}" width="400" height="400"><h2>${p.name}</h2><p class="price">$${p.price}</p></article>`}products().then(ps=>{document.querySelector('#product-grid').innerHTML=ps.map(card).join('')}).catch(e=>{document.querySelector('#product-grid').textContent=e.message})
